  #coin-hero { max-width: 90vw; max-height: 60vh; width: 500px; height: 500px; background: #000; border-radius: 8px; box-shadow: 0 0 40px rgba(255,215,0,0.15); }
  .about { padding: 4rem 2rem; max-width: 800px; margin: 0 auto; text-align: center; }
  .about h2 { font-size: 2.5rem; margin-bottom: 1.5rem; color: #ffd700; letter-spacing: 0.02em; }
  .about p { font-size: 1.1rem; color: #ccc; max-width: 600px; margin: 0 auto; }
  .collection { padding: 3rem 2rem; background: #0a0a0a; }
  .collection h2 { text-align: center; color: #ffd700; margin-bottom: 2.5rem; font-size: 2rem; }
  .grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 2rem; max-width: 1000px; margin: 0 auto; }
  .edition { background: #141414; border: 1px solid #2a2a2a; border-radius: 12px; padding: 1.5rem; text-align: center; display: flex; flex-direction: column; align-items: center; transition: transform 0.2s, box-shadow 0.2s; }
  .edition:hover { transform: translateY(-4px); box-shadow: 0 12px 30px rgba(0,0,0,0.5); }
  .edition-canvas { width: 100%; max-width: 240px; height: 240px; background: #000; border-radius: 8px; margin-bottom: 1rem; }
  .edition-status { margin-top: 0.5rem; font-weight: 600; font-size: 0.9rem; color: #888; }
  .edition[data-state="sold-out"] .edition-status { color: #ff4444; }
  .edition[data-state="coming-soon"] .edition-status { color: #44aaff; }
  button.buy { margin-top: 1rem; padding: 0.85rem 2rem; background: linear-gradient(180deg, #ffd700, #e6c200); color: #000; border: none; border-radius: 6px; font-weight: 700; font-size: 0.95rem; cursor: pointer; transition: background 0.2s, transform 0.1s; }
  button.buy:hover { background: linear-gradient(180deg, #ffe066, #ffd700); }
