    </div>
  </div>
</section>
<script>
// ========== Matrix math ==========
function mat4Create() { return new Float32Array(16); }
function mat4Identity(out) { out[0]=1;out[1]=0;out[2]=0;out[3]=0;out[4]=0;out[5]=1;out[6]=0;out[7]=0;out[8]=0;out[9]=0;out[10]=1;out[11]=0;out[12]=0;out[13]=0;out[14]=0;out[15]=1; return out; }
function mat4Perspective(out, fovy, aspect, near, far) {
  const f = 1.0 / Math.tan(fovy / 2);
  out[0] = f / aspect; out[1] = 0; out[2] = 0; out[3] = 0;
  out[4] = 0; out[5] = f; out[6] = 0; out[7] = 0;
  out[8] = 0; out[9] = 0; out[10] = (far + near) / (near - far); out[11] = -1;
  out[12] = 0; out[13] = 0; out[14] = (2 * far * near) / (near - far); out[15] = 0;
  return out;
}
function mat4LookAt(out, eye, center, up) {
  let x0,x1,x2,y0,y1,y2,z0,z1,z2,len;
  const eyex=eye[0],eyey=eye[1],eyez=eye[2], cx=center[0],cy=center[1],cz=center[2], ux=up[0],uy=up[1],uz=up[2];
  z0=eyex-cx; z1=eyey-cy; z2=eyez-cz; len=1/Math.hypot(z0,z1,z2); z0*=len;z1*=len;z2*=len;
  x0=uy*z2-uz*z1; x1=uz*z0-ux*z2; x2=ux*z1-uy*z0; len=Math.hypot(x0,x1,x2); if(!len)return null; len=1/len; x0*=len;x1*=len;x2*=len;
  y0=z1*x2-z2*x1; y1=z2*x0-z0*x2; y2=z0*x1-z1*x0; len=Math.hypot(y0,y1,y2); if(!len)return null; len=1/len; y0*=len;y1*=len;y2*=len;
  out[0]=x0;out[1]=y0;out[2]=z0;out[3]=0; out[4]=x1;out[5]=y1;out[6]=z1;out[7]=0; out[8]=x2;out[9]=y2;out[10]=z2;out[11]=0;
  out[12]=-(x0*eyex+x1*eyey+x2*eyez); out[13]=-(y0*eyex+y1*eyey+y2*eyez); out[14]=-(z0*eyex+z1*eyey+z2*eyez); out[15]=1;
  return out;
}
function mat4Multiply(out, a, b) {
  const a00=a[0],a01=a[1],a02=a[2],a03=a[3], a10=a[4],a11=a[5],a12=a[6],a13=a[7], a20=a[8],a21=a[9],a22=a[10],a23=a[11], a30=a[12],a31=a[13],a32=a[14],a33=a[15];
  let b0=b[0],b1=b[1],b2=b[2],b3=b[3];
  out[0]=b0*a00+b1*a10+b2*a20+b3*a30; out[1]=b0*a01+b1*a11+b2*a21+b3*a31; out[2]=b0*a02+b1*a12+b2*a22+b3*a32; out[3]=b0*a03+b1*a13+b2*a23+b3*a33;
  b0=b[4];b1=b[5];b2=b[6];b3=b[7];
  out[4]=b0*a00+b1*a10+b2*a20+b3*a30; out[5]=b0*a01+b1*a11+b2*a21+b3*a31; out[6]=b0*a02+b1*a12+b2*a22+b3*a32; out[7]=b0*a03+b1*a13+b2*a23+b3*a33;
  b0=b[8];b1=b[9];b2=b[10];b3=b[11];
  out[8]=b0*a00+b1*a10+b2*a20+b3*a30; out[9]=b0*a01+b1*a11+b2*a21+b3*a31; out[10]=b0*a02+b1*a12+b2*a22+b3*a32; out[11]=b0*a03+b1*a13+b2*a23+b3*a33;
  b0=b[12];b1=b[13];b2=b[14];b3=b[15];
  out[12]=b0*a00+b1*a10+b2*a20+b3*a30; out[13]=b0*a01+b1*a11+b2*a21+b3*a31; out[14]=b0*a02+b1*a12+b2*a22+b3*a32; out[15]=b0*a03+b1*a13+b2*a23+b3*a33;
  return out;
}
function mat4RotateX(out, a, rad) {
  const s=Math.sin(rad), c=Math.cos(rad); const a10=a[4],a11=a[5],a12=a[6],a13=a[7], a20=a[8],a21=a[9],a22=a[10],a23=a[11];
  out[4]=a10*c+a20*s; out[5]=a11*c+a21*s; out[6]=a12*c+a22*s; out[7]=a13*c+a23*s;
  out[8]=a20*c-a10*s; out[9]=a21*c-a11*s; out[10]=a22*c-a12*s; out[11]=a23*c-a13*s;
  if(a!==out){out[0]=a[0];out[1]=a[1];out[2]=a[2];out[3]=a[3];out[12]=a[12];out[13]=a[13];out[14]=a[14];out[15]=a[15];}
  return out;
}
function mat4RotateY(out, a, rad) {
  const s=Math.sin(rad), c=Math.cos(rad); const a00=a[0],a01=a[1],a02=a[2],a03=a[3], a20=a[8],a21=a[9],a22=a[10],a23=a[11];
  out[0]=a00*c-a20*s; out[1]=a01*c-a21*s; out[2]=a02*c-a22*s; out[3]=a03*c-a23*s;
  out[8]=a00*s+a20*c; out[9]=a01*s+a21*c; out[10]=a02*s+a22*c; out[11]=a03*s+a23*c;
  if(a!==out){out[4]=a[4];out[5]=a[5];out[6]=a[6];out[7]=a[7];out[12]=a[12];out[13]=a[13];out[14]=a[14];out[15]=a[15];}
  return out;
}
function mat3Create() { return new Float32Array(9); }
function mat3NormalFromMat4(out, a) {
  const a00=a[0],a01=a[1],a02=a[2],a03=a[3], a10=a[4],a11=a[5],a12=a[6],a13=a[7], a20=a[8],a21=a[9],a22=a[10],a23=a[11], a30=a[12],a31=a[13],a32=a[14],a33=a[15];
  const b00=a00*a11-a01*a10, b01=a00*a12-a02*a10, b02=a00*a13-a03*a10, b03=a01*a12-a02*a11, b04=a01*a13-a03*a11, b05=a02*a13-a03*a12;
  const b06=a20*a31-a21*a30, b07=a20*a32-a22*a30, b08=a20*a33-a23*a30, b09=a21*a32-a22*a31, b10=a21*a33-a23*a31, b11=a22*a33-a23*a32;
  const det=b00*b11-b01*b10+b02*b09+b03*b08-b04*b07+b05*b06; if(!det)return null; const invDet=1/det;
  out[0]=(a11*b11-a12*b10+a13*b09)*invDet; out[1]=(a12*b08-a10*b11-a13*b07)*invDet; out[2]=(a10*b10-a11*b08+a13*b06)*invDet;
  out[3]=(a02*b10-a01*b11-a03*b09)*invDet; out[4]=(a00*b11-a02*b08+a03*b07)*invDet; out[5]=(a01*b08-a00*b10-a03*b06)*invDet;
  out[6]=(a31*b05-a32*b04+a33*b03)*invDet; out[7]=(a32*b02-a30*b05-a33*b01)*invDet; out[8]=(a30*b04-a31*b02+a33*b00)*invDet;
  return out;
}

// ========== Coin geometry ==========
function createCoinGeometryData() {
  const radius=1.0, halfHeight=0.1, segments=64;
  const positions=[], normals=[], texCoords=[], faceIds=[], indices=[];
  // Front cap (face 0)
  positions.push(0,0,halfHeight); normals.push(0,0,1); texCoords.push(0.5,0.5); faceIds.push(0);
  const centerIdx=0;
  for(let i=0;i<=segments;i++){ const th=i/segments*Math.PI*2, x=radius*Math.cos(th), y=radius*Math.sin(th);
    positions.push(x,y,halfHeight); normals.push(0,0,1); texCoords.push(0.5+0.5*Math.cos(th),0.5+0.5*Math.sin(th)); faceIds.push(0);
  }
  for(let i=0;i<segments;i++) indices.push(centerIdx, centerIdx+i+1, centerIdx+i+2);
  // Back cap (face 1)
  const backCenterIdx=positions.length/3;
  positions.push(0,0,-halfHeight); normals.push(0,0,-1); texCoords.push(0.5,0.5); faceIds.push(1);
  for(let i=0;i<=segments;i++){ const th=i/segments*Math.PI*2, x=radius*Math.cos(th), y=radius*Math.sin(th);
    positions.push(x,y,-halfHeight); normals.push(0,0,-1); texCoords.push(0.5+0.5*Math.cos(th),0.5+0.5*Math.sin(th)); faceIds.push(1);
  }
  for(let i=0;i<segments;i++) indices.push(backCenterIdx, backCenterIdx+i+2, backCenterIdx+i+1);
  // Side (face 2)
  const sideStart=positions.length/3;
  for(let i=0;i<=segments;i++){ const th=i/segments*Math.PI*2, nx=Math.cos(th), ny=Math.sin(th);
    positions.push(radius*nx,radius*ny,halfHeight); normals.push(nx,ny,0); texCoords.push(i/segments,0); faceIds.push(2);
    positions.push(radius*nx,radius*ny,-halfHeight); normals.push(nx,ny,0); texCoords.push(i/segments,1); faceIds.push(2);
  }
  for(let i=0;i<segments;i++){ const b=sideStart+i*2;
    indices.push(b, b+1, b+2); indices.push(b+1, b+3, b+2);
  }
  return {positions, normals, texCoords, faceIds, indices};
}

// ========== Texture canvases ==========
function createTextureCanvases() {
  const size=512;
  const front=document.createElement('canvas'); front.width=front.height=size;
  const fctx=front.getContext('2d');
  fctx.fillStyle='#fff'; fctx.fillRect(0,0,size,size);
  fctx.strokeStyle='#000'; fctx.lineWidth=8;
  fctx.beginPath(); fctx.arc(size/2,size/2,size/2-10,0,Math.PI*2); fctx.stroke();
  fctx.fillStyle='#000'; fctx.textAlign='center'; fctx.textBaseline='middle';
  fctx.font='bold 48px serif'; fctx.fillText('WASTED',size/2,size/2-60);
  fctx.font='32px serif'; fctx.fillText('TOKEN',size/2,size/2);
  fctx.font='24px sans-serif'; fctx.fillText('MINT',size/2,size/2+60);
  fctx.strokeStyle='#000'; fctx.lineWidth=2;
  fctx.beginPath(); fctx.arc(size/2,size/2,size/2-40,-Math.PI/6,-5*Math.PI/6); fctx.stroke();
  fctx.beginPath(); fctx.arc(size/2,size/2,size/2-40,Math.PI/6,5*Math.PI/6); fctx.stroke();

  const back=document.createElement('canvas'); back.width=back.height=size;
  const bctx=back.getContext('2d');
  bctx.fillStyle='#fff'; bctx.fillRect(0,0,size,size);
  bctx.strokeStyle='#000'; bctx.lineWidth=8;
  bctx.beginPath(); bctx.arc(size/2,size/2,size/2-10,0,Math.PI*2); bctx.stroke();
  bctx.fillStyle='#000'; bctx.textAlign='center'; bctx.textBaseline='middle';
  bctx.font='bold 40px sans-serif'; bctx.fillText('10,000',size/2,size/2-30);
  bctx.font='28px sans-serif'; bctx.fillText('TOKENS',size/2,size/2+30);
  bctx.font='20px serif'; bctx.fillText('EST. 2024',size/2,size/2+80);
  return {front, back};
}

// ========== CoinRenderer class ==========
class CoinRenderer {
  constructor(canvas, options={}) {
    this.canvas=canvas; this.gl=canvas.getContext('webgl',{antialias:true,alpha:false});
    if(!this.gl) throw new Error('WebGL unsupported');
    this.metalColor=options.metalColor||[1.0,0.84,0.0];
    this.autoAnimate=options.autoAnimate||false;
    this.animationId=null; this.currentT=0;

    if(!CoinRenderer.textureCanvases) CoinRenderer.textureCanvases=createTextureCanvases();
    this.frontCanvas=CoinRenderer.textureCanvases.front;
    this.backCanvas=CoinRenderer.textureCanvases.back;

    this.initShaders(); this.initGeometry(); this.initTextures(); this.initUniforms();
    this.resize(); window.addEventListener('resize',()=>this.resize());
    if(this.autoAnimate) this.startAnimation();
  }
  initShaders() {
    const gl=this.gl;
    const vsSrc=`attribute vec3 aPosition;attribute vec3 aNormal;attribute vec2 aTexCoord;attribute float aFace;
uniform mat4 uModelViewMatrix;uniform mat4 uProjectionMatrix;uniform mat3 uNormalMatrix;
varying vec2 vTexCoord;varying vec3 vNormal;varying vec3 vWorldPos;varying float vFace;
void main(){vec4 w=uModelViewMatrix*vec4(aPosition,1.0);vWorldPos=w.xyz;vNormal=normalize(uNormalMatrix*aNormal);vTexCoord=aTexCoord;vFace=aFace;gl_Position=uProjectionMatrix*w;}`;
    const fsSrc=`precision highp float;varying vec2 vTexCoord;varying vec3 vNormal;varying vec3 vWorldPos;varying float vFace;
uniform sampler2D uFrontTexture;uniform sampler2D uBackTexture;uniform vec3 uMetalColor;uniform vec3 uLightDir;uniform float uShininess;
void main(){vec3 n=normalize(vNormal);vec3 v=normalize(-vWorldPos);vec3 l=normalize(uLightDir);
vec3 base; if(vFace<0.5){base=texture2D(uFrontTexture,vTexCoord).rgb*uMetalColor;}
else if(vFace<1.5){base=texture2D(uBackTexture,vTexCoord).rgb*uMetalColor;}
else{float ridges=sin(vTexCoord.x*40.0*6.283185);float rf=smoothstep(0.0,0.1,ridges)-smoothstep(0.9,1.0,ridges);base=uMetalColor*(0.7+0.3*rf);}
float diff=max(dot(n,l),0.0);vec3 r=reflect(-l,n);float spec=pow(max(dot(v,r),0.0),uShininess);
vec3 col=base*diff*0.8+vec3(1.0)*spec*1.2+base*0.2;gl_FragColor=vec4(col,1.0);}`;
    const vs=this.compileShader(gl.VERTEX_SHADER,vsSrc), fs=this.compileShader(gl.FRAGMENT_SHADER,fsSrc);
    this.program=gl.createProgram(); gl.attachShader(this.program,vs); gl.attachShader(this.program,fs); gl.linkProgram(this.program);
    if(!gl.getProgramParameter(this.program,gl.LINK_STATUS)) throw new Error(gl.getProgramInfoLog(this.program));
    gl.useProgram(this.program);
  }
  compileShader(type,src){const gl=this.gl;const s=gl.createShader(type);gl.shaderSource(s,src);gl.compileShader(s);if(!gl.getShaderParameter(s,gl.COMPILE_STATUS)){console.error(gl.getShaderInfoLog(s));gl.deleteShader(s);return null;}return s;}
  initGeometry() {
    const gl=this.gl, geo=createCoinGeometryData(); this.indexCount=geo.indices.length;
    this.posBuf=gl.createBuffer(); gl.bindBuffer(gl.ARRAY_BUFFER,this.posBuf); gl.bufferData(gl.ARRAY_BUFFER,new Float32Array(geo.positions),gl.STATIC_DRAW);
    this.norBuf=gl.createBuffer(); gl.bindBuffer(gl.ARRAY_BUFFER,this.norBuf); gl.bufferData(gl.ARRAY_BUFFER,new Float32Array(geo.normals),gl.STATIC_DRAW);
    this.texBuf=gl.createBuffer(); gl.bindBuffer(gl.ARRAY_BUFFER,this.texBuf); gl.bufferData(gl.ARRAY_BUFFER,new Float32Array(geo.texCoords),gl.STATIC_DRAW);
    this.faceBuf=gl.createBuffer(); gl.bindBuffer(gl.ARRAY_BUFFER,this.faceBuf); gl.bufferData(gl.ARRAY_BUFFER,new Float32Array(geo.faceIds),gl.STATIC_DRAW);
    this.idxBuf=gl.createBuffer(); gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER,this.idxBuf); gl.bufferData(gl.ELEMENT_ARRAY_BUFFER,new Uint16Array(geo.indices),gl.STATIC_DRAW);
    this.aPos=gl.getAttribLocation(this.program,'aPosition'); this.aNor=gl.getAttribLocation(this.program,'aNormal');
    this.aTex=gl.getAttribLocation(this.program,'aTexCoord'); this.aFace=gl.getAttribLocation(this.program,'aFace');
    gl.enableVertexAttribArray(this.aPos); gl.enableVertexAttribArray(this.aNor); gl.enableVertexAttribArray(this.aTex); gl.enableVertexAttribArray(this.aFace);
  }
  initTextures() {
    const gl=this.gl;
    this.frontTex=gl.createTexture(); gl.bindTexture(gl.TEXTURE_2D,this.frontTex);
    gl.texImage2D(gl.TEXTURE_2D,0,gl.RGBA,gl.RGBA,gl.UNSIGNED_BYTE,this.frontCanvas);
    gl.generateMipmap(gl.TEXTURE_2D); gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_S,gl.CLAMP_TO_EDGE); gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_T,gl.CLAMP_TO_EDGE); gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MIN_FILTER,gl.LINEAR_MIPMAP_LINEAR); gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MAG_FILTER,gl.LINEAR);
    this.backTex=gl.createTexture(); gl.bindTexture(gl.TEXTURE_2D,this.backTex);
    gl.texImage2D(gl.TEXTURE_2D,0,gl.RGBA,gl.RGBA,gl.UNSIGNED_BYTE,this.backCanvas);
    gl.generateMipmap(gl.TEXTURE_2D); gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_S,gl.CLAMP_TO_EDGE); gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_T,gl.CLAMP_TO_EDGE); gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MIN_FILTER,gl.LINEAR_MIPMAP_LINEAR); gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MAG_FILTER,gl.LINEAR);
  }
  initUniforms() {
    const gl=this.gl;
    this.uMV=gl.getUniformLocation(this.program,'uModelViewMatrix');
    this.uProj=gl.getUniformLocation(this.program,'uProjectionMatrix');
    this.uNorm=gl.getUniformLocation(this.program,'uNormalMatrix');
    this.uFront=gl.getUniformLocation(this.program,'uFrontTexture');
    this.uBack=gl.getUniformLocation(this.program,'uBackTexture');
    this.uMetal=gl.getUniformLocation(this.program,'uMetalColor');
    this.uLight=gl.getUniformLocation(this.program,'uLightDir');
    this.uShine=gl.getUniformLocation(this.program,'uShininess');
  }
  resize() {
    const gl=this.gl, dpr=window.devicePixelRatio||1;
    const w=this.canvas.clientWidth*dpr, h=this.canvas.clientHeight*dpr;
    if(this.canvas.width!==w||this.canvas.height!==h){this.canvas.width=w;this.canvas.height=h;gl.viewport(0,0,w,h);}
    this.projMat=mat4Create(); mat4Perspective(this.projMat,45*Math.PI/180,w/h,0.1,100);
  }
  render(t) {
    const gl=this.gl; this.currentT=t; this.resize();
    gl.clearColor(0.02,0.02,0.02,1); gl.clear(gl.COLOR_BUFFER_BIT|gl.DEPTH_BUFFER_BIT);
    gl.enable(gl.DEPTH_TEST); gl.enable(gl.CULL_FACE); gl.cullFace(gl.BACK);
    gl.useProgram(this.program);
    // bind attributes
    gl.bindBuffer(gl.ARRAY_BUFFER,this.posBuf); gl.vertexAttribPointer(this.aPos,3,gl.FLOAT,false,0,0);
    gl.bindBuffer(gl.ARRAY_BUFFER,this.norBuf); gl.vertexAttribPointer(this.aNor,3,gl.FLOAT,false,0,0);
