    bronze: { base: '#cd7f32', light: '#e8a86b', dark: '#8b5a2b', rough: 0.35 },
    silver: { base: '#c0c0c0', light: '#f0f0f0', dark: '#888888', rough: 0.15 },
    gold:   { base: '#ffd700', light: '#fff8a0', dark: '#b89600', rough: 0.1 },
    black:  { base: '#0a0a0a', light: '#1a1a1a', dark: '#000000', rough: 0.05 }
  };
  const m = metals[metal];

  function drawMetalSurface(ctx, lightDir) {
    // Procedural brushed metal with anisotropic highlights
    const grad = ctx.createRadialGradient(size*0.5, size*0.5, 0, size*0.5, size*0.5, size*0.7);
    grad.addColorStop(0, m.light);
    grad.addColorStop(0.5, m.base);
    grad.addColorStop(1, m.dark);
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, size, size);

    // Brushed texture
    ctx.globalCompositeOperation = 'overlay';
    ctx.globalAlpha = 0.15;
    for (let i = 0; i < size; i += 2) {
      const y = i + Math.random() * 2;
      const alpha = 0.05 + Math.random() * 0.1;
      ctx.strokeStyle = `rgba(255,255,255,${alpha})`;
      ctx.beginPath();
      ctx.moveTo(0, y);
      ctx.lineTo(size, y + (Math.random()-0.5)*4);
      ctx.stroke();
    }
    ctx.globalAlpha = 0.1;
    for (let i = 0; i < size; i += 3) {
      const y = i + Math.random() * 3;
      const alpha = 0.03 + Math.random() * 0.08;
      ctx.strokeStyle = `rgba(0,0,0,${alpha})`;
      ctx.beginPath();
      ctx.moveTo(0, y);
      ctx.lineTo(size, y + (Math.random()-0.5)*6);
      ctx.stroke();
    }
    ctx.globalCompositeOperation = 'source-over';
    ctx.globalAlpha = 1;

    // Subtle noise
    const imgData = ctx.getImageData(0, 0, size, size);
    const data = imgData.data;
    for (let i = 0; i < data.length; i += 4) {
      const n = (Math.random() - 0.5) * 12 * m.rough;
      data[i] = Math.min(255, Math.max(0, data[i] + n));
      data[i+1] = Math.min(255, Math.max(0, data[i+1] + n));
      data[i+2] = Math.min(255, Math.max(0, data[i+2] + n));
    }
    ctx.putImageData(imgData, 0, 0);
  }

  // Front face - WastedToken emblem
  drawMetalSurface(fx);
  const cx = size/2, cy = size/2, r = size*0.42;

  // Outer ring
  fx.strokeStyle = m.light;
  fx.lineWidth = 4;
  fx.beginPath();
  fx.arc(cx, cy, r, 0, Math.PI*2);
  fx.stroke();

  fx.strokeStyle = m.dark;
  fx.lineWidth = 2;
  fx.beginPath();
  fx.arc(cx, cy, r-6, 0, Math.PI*2);
  fx.stroke();

  // Central emblem - stylized 'W' / token
  fx.save();
  fx.translate(cx, cy);
  fx.scale(1, 1);

  // Raised relief effect via shading
  const emblemR = r * 0.65;
  // Background circle for emblem
  const eg = fx.createRadialGradient(0, -emblemR*0.3, 0, 0, 0, emblemR);
  eg.addColorStop(0, m.light);
