  fx.lineTo(-spacing*1.5, -barH/2);
  fx.lineTo(-spacing*1.5, barH/2);
  fx.lineTo(-spacing*1.5 - barW, barH/2);
  fx.closePath();
  fx.fill();

  // Middle bar (taller)
