  const hg = fx.createLinearGradient(-emblemR, -emblemR, emblemR, emblemR);
  hg.addColorStop(0, 'rgba(255,255,255,0.3)');
  hg.addColorStop(0.5, 'rgba(255,255,255,0)');
  hg.addColorStop(1, 'rgba(0,0,0,0.2)');
  fx.fillStyle = hg;
  fx.beginPath();
  fx.arc(0, 0, emblemR, 0, Math.PI*2);
  fx.fill();
  fx.globalCompositeOperation = 'source-over';

  // "WASTEDTOKEN MINT" text around ring
  fx.font = `bold ${size*0.035}px system-ui, sans-serif`;
  fx.textAlign = 'center';
  fx.textBaseline = 'middle';
  const textR = r * 0.85;
  const text = "WASTEDTOKEN MINT  •  EST. 2019  •  DENVER";
  const chars = text.split('');
  const totalAngle = chars.length * 0.06;
  fx.save();
  fx.rotate(-totalAngle/2);
  chars.forEach((ch, i) => {
    fx.save();
    fx.rotate(i * 0.06);
