    fx.fillStyle = m.dark;
    fx.fillText(ch, 0, -textR+1);
    fx.fillStyle = m.light;
    fx.fillText(ch, 0, -textR-1);
    fx.fillStyle = m.base;
    fx.fillText(ch, 0, -textR);
    fx.restore();
  });
  fx.restore();

  fx.restore();

  // Back face - denomination
  drawMetalSurface(bx);

  // Outer ring
  bx.strokeStyle = m.light;
  bx.lineWidth = 4;
  bx.beginPath();
  bx.arc(cx, cy, r, 0, Math.PI*2);
  bx.stroke();
  bx.strokeStyle = m.dark;
  bx.lineWidth = 2;
  bx.beginPath();
  bx.arc(cx, cy, r-6, 0, Math.PI*2);
  bx.stroke();

