  const bg = bx.createRadialGradient(0, -r*0.2, 0, 0, 0, r*0.75);
  bg.addColorStop(0, m.light);
  bg.addColorStop(0.5, m.base);
  bg.addColorStop(1, m.dark);
  bx.fillStyle = bg;
  bx.beginPath();
  bx.arc(0, 0, r*0.75, 0, Math.PI*2);
  bx.fill();

  // "10,000 TOKENS"
  bx.font = `bold ${size*0.07}px system-ui, sans-serif`;
  bx.textAlign = 'center';
  bx.textBaseline = 'middle';

  // Embossed text
  bx.fillStyle = m.dark;
  bx.fillText("10,000", 1, 3);
  bx.fillStyle = m.light;
  bx.fillText("10,000", -1, -3);
  bx.fillStyle = m.base;
  bx.fillText("10,000", 0, 0);

  bx.font = `${size*0.035}px system-ui, sans-serif`;
  bx.fillStyle = m.dark;
  bx.fillText("TOKENS", 1, size*0.06+3);
  bx.fillStyle = m.light;
  bx.fillText("TOKENS", -1, size*0.06-3);
  bx.fillStyle = m.base;
  bx.fillText("TOKENS", 0, size*0.06);

  // Serial number placeholder
  bx.font = `${size*0.02}px monospace`;
  bx.fillStyle = m.dark;
  bx.fillText("SN: WT-XXXX-XXXX", 1, size*0.28+1);
  bx.fillStyle = m.light;
  bx.fillText("SN: WT-XXXX-XXXX", -1, size*0.28-1);
  bx.fillStyle = m.base;
  bx.fillText("SN: WT-XXXX-XXXX", 0, size*0.28);

  bx.restore();

  // Convert to textures
  return {
    front: front,
    back: back
  };
}

// Generate normal map for reeded edge + embossed details
function createNormalMap(metal, face) {
  const size = 512;
  const canvas = document.createElement('canvas');
  canvas.width = canvas.height = size;
  const ctx = canvas.getContext('2d');

  // Base normal (flat = 128,128,255)
  const imgData = ctx.createImageData(size, size);
  const data = imgData.data;

  const cx = size/2, cy = size/2;
  const faceR = size * 0.42;
  const metals = {
    bronze: { relief: 1.0 },
    silver: { relief: 1.2 },
    gold: { relief: 1.1 },
    black: { relief: 0.8 }
  };
  const relief = metals[metal].relief;

  for (let y = 0; y < size; y++) {
    for (let x = 0; x < size; x++) {
      const dx = x - cx;
      const dy = y - cy;
      const dist = Math.sqrt(dx*dx + dy*dy);
      const angle = Math.atan2(dy, dx);

      let nx = 0, ny = 0, nz = 1;

      if (face === 'front') {
        // Emblem relief
        if (dist < faceR * 0.65) {
          // W shape normal perturbation
          const localX = dx / (faceR * 0.65);
          const localY = dy / (faceR * 0.65);
          // Three bars
          const barW = 0.18;
          const barH = 0.7;
          const spacing = 0.22;

          let inBar = false;
          let barCenterX = 0;

          if (Math.abs(localX + spacing*1.5 + barW/2) < barW/2 && Math.abs(localY) < barH/2) {
            inBar = true; barCenterX = -spacing*1.5 - barW/2;
          } else if (Math.abs(localX) < barW/2 && Math.abs(localY) < barH/2*1.2) {
            inBar = true; barCenterX = 0;
          } else if (Math.abs(localX - spacing*1.5 - barW/2) < barW/2 && Math.abs(localY) < barH/2) {
            inBar = true; barCenterX = spacing*1.5 + barW/2;
          }

          if (inBar) {
            const h = 0.5 * relief * (1 - Math.abs(localY)/(barH/2));
            nz = 1 + h;
            nx = -(x - cx - barCenterX*faceR*0.65) * 0.002 * relief;
            ny = -dy * 0.002 * relief;
          }
        }
        // Outer ring bevel
        if (dist > faceR * 0.9 && dist < faceR) {
          const f = (dist - faceR*0.9) / (faceR*0.1);
          nz = 1 + f * 0.3 * relief;
          ny = -dy/dist * f * 0.3 * relief;
          nx = -dx/dist * f * 0.3 * relief;
        }
      } else {
        // Back face - "10,000 TOKENS" text relief
        if (dist < faceR * 0.75) {
          // Large numbers relief
          const textY = dy + size*0.05;
          if (Math.abs(textY) < size*0.06 && Math.abs(dx) < size*0.25) {
            nz = 1 + 0.3 * relief;
            ny = -0.1 * relief * Math.sign(textY);
          }
          // TOKENS text
          if (Math.abs(dy - size*0.06) < size*0.03 && Math.abs(dx) < size*0.15) {
            nz = 1 + 0.2 * relief;
          }
        }
        // Outer ring bevel
        if (dist > faceR * 0.9 && dist < faceR) {
          const f = (dist - faceR*0.9) / (faceR*0.1);
          nz = 1 + f * 0.3 * relief;
          ny = -dy/dist * f * 0.3 * relief;
          nx = -dx/dist * f * 0.3 * relief;
        }
      }

      // Normalize
      const len = Math.sqrt(nx*nx + ny*ny + nz*nz);
      nx /= len; ny /= len; nz /= len;

      const i = (y*size + x)*4;
      data[i] = Math.round((nx*0.5 + 0.5) * 255);
      data[i+1] = Math.round((ny*0.5 + 0.5) * 255);
      data[i+2] = Math.round((nz*0.5 + 0.5) * 255);
      data[i+3] = 255;
    }
  }
  ctx.putImageData(imgData, 0, 0);
  return canvas;
}

// ============ WebGL Coin Renderer ============
class CoinRenderer {
  constructor(canvas, options = {}) {
    this.canvas = canvas;
    this.gl = canvas.getContext('webgl2', { antialias: true, alpha: false, preserveDrawingBuffer: true });
    if (!this.gl) throw new Error('WebGL2 not supported');

    this.width = canvas.width;
    this.height = canvas.height;
    this.metal = options.metal || 'bronze';
    this.isHero = options.isHero || false;

    this.initShaders();
    this.initGeometry();
    this.initTextures();
    this.initUniforms();

    this.time = 0;
    this.paused = false;
    this.animId = null;

    this.resize();
    this.render(0);
  }

  initShaders() {
    const gl = this.gl;

    // Vertex shader - handles coin geometry, reeded edge, face normals
    const vsSource = `#version 300 es
    precision highp float;

    layout(location=0) in vec3 aPos;
    layout(location=1) in vec3 aNormal;
    layout(location=2) in vec2 aUv;
    layout(location=3) in float aFace; // 0=edge, 1=front, 2=back

    uniform mat4 uModel;
    uniform mat4 uView;
    uniform mat4 uProj;
    uniform float uTime;
    uniform float uReedAmplitude;

    out vec3 vWorldPos;
    out vec3 vNormal;
    out vec2 vUv;
    out float vFace;
    out vec3 vViewDir;
    out vec3 vLightDir;

    // Procedural environment direction
    vec3 envDir(vec3 n) {
      return normalize(vec3(n.x, n.y + 0.3, n.z + 0.5));
    }

    void main() {
      vec3 pos = aPos;
      vec3 normal = aNormal;

      // Reeded edge displacement
      if (aFace < 0.5) {
        float angle = atan(pos.x, pos.z);
        float reeds = 120.0; // number of reeds
        float displacement = uReedAmplitude * sin(angle * reeds + uTime * 0.5);
        pos += normal * displacement;
        // Recalculate normal for displaced edge
        float dAngle = 0.001;
        float d1 = uReedAmplitude * sin((angle+dAngle) * reeds + uTime * 0.5);
        float d2 = uReedAmplitude * sin((angle-dAngle) * reeds + uTime * 0.5);
        vec3 tangent = normalize(vec3(-pos.z, 0.0, pos.x));
        vec3 bitangent = normalize(cross(normal, tangent));
        normal = normalize(normal + tangent * (d1-d2)/(2.0*dAngle) * reeds);
      }

      vec4 worldPos = uModel * vec4(pos, 1.0);
      vWorldPos = worldPos.xyz;
      vNormal = mat3(uModel) * normal;
      vUv = aUv;
      vFace = aFace;

      vec3 viewPos = (uView * worldPos).xyz;
      vViewDir = normalize(-viewPos);
      vLightDir = normalize(vec3(0.5, 1.0, 0.3)); // Key light direction

      gl_Position = uProj * uView * worldPos;
    }
    `;

    // Fragment shader - metallic PBR with procedural environment
    const fsSource = `#version 300 es
    precision highp float;

    in vec3 vWorldPos;
    in vec3 vNormal;
    in vec2 vUv;
    in float vFace;
    in vec3 vViewDir;
    in vec3 vLightDir;

    uniform sampler2D uFrontColor;
    uniform sampler2D uBackColor;
    uniform sampler2D uFrontNormal;
    uniform sampler2D uBackNormal;
    uniform sampler2D uEdgeColor;
    uniform vec3 uBaseColor;
    uniform float uRoughness;
    uniform float uMetalness;
    uniform float uTime;
    uniform bool uIsHero;

    out vec4 fragColor;

    // GGX distribution
    float D_GGX(vec3 N, vec3 H, float roughness) {
      float a = roughness * roughness;
      float a2 = a * a;
      float NdotH = max(dot(N, H), 0.0);
      float NdotH2 = NdotH * NdotH;
      float denom = NdotH2 * (a2 - 1.0) + 1.0;
      return a2 / (PI * denom * denom);
    }

    // Schlick-GGX geometry
    float G_SchlickGGX(float NdotV, float roughness) {
      float r = roughness + 1.0;
      float k = (r * r) / 8.0;
      return NdotV / (NdotV * (1.0 - k) + k);
    }
    float G_Smith(vec3 N, vec3 V, vec3 L, float roughness) {
      float NdotV = max(dot(N, V), 0.0);
      float NdotL = max(dot(N, L), 0.0);
      return G_SchlickGGX(NdotV, roughness) * G_SchlickGGX(NdotL, roughness);
    }

    // Fresnel-Schlick
    vec3 F_Schlick(float cosTheta, vec3 F0) {
      return F0 + (1.0 - F0) * pow(1.0 - cosTheta, 5.0);
    }

    // Procedural environment (gradient skybox)
    vec3 sampleEnv(vec3 R) {
      float t = R.y * 0.5 + 0.5;
      // Horizon gradient
      vec3 horizon = mix(vec3(0.15, 0.12, 0.1), vec3(0.05, 0.05, 0.08), t);
      // Sun highlight
      vec3 sunDir = normalize(vec3(0.3, 0.8, 0.4));
      float sun = max(dot(R, sunDir), 0.0);
      sun = pow(sun, 128.0) * 3.0;
      // Rim light
      vec3 rimDir = normalize(vec3(-0.4, 0.2, -0.6));
      float rim = max(dot(R, rimDir), 0.0);
      rim = pow(rim, 32.0) * 0.8;
      return horizon + vec3(sun) + vec3(rim);
    }

    // Procedural edge color (reeded metal)
    vec3 getEdgeColor(vec2 uv) {
      float angle = atan(uv.x - 0.5, uv.y - 0.5);
      float reeds = 120.0;
      float groove = sin(angle * reeds + uTime * 0.5) * 0.5 + 0.5;
      vec3 base = uBaseColor;
      vec3 highlight = mix(base * 0.6, base * 1.4, groove);
      return highlight;
    }

    void main() {
      vec3 N = normalize(vNormal);
      vec3 V = vViewDir;
      vec3 L = vLightDir;
      vec3 H = normalize(V + L);

      // Face selection
      vec3 baseColor = uBaseColor;
      float roughness = uRoughness;
      float metalness = uMetalness;
      vec3 normalMap = vec3(0, 0, 1);

      if (vFace > 1.5) { // Back face
        baseColor = texture(uBackColor, vUv).rgb;
        normalMap = texture(uBackNormal, vUv).rgb * 2.0 - 1.0;
      } else if (vFace > 0.5) { // Front face
        baseColor = texture(uFrontColor, vUv).rgb;
        normalMap = texture(uFrontNormal, vUv).rgb * 2.0 - 1.0;
      } else { // Edge
        baseColor = getEdgeColor(vUv);
        // Edge normal perturbation from reeds
        float angle = atan(vWorldPos.x, vWorldPos.z);
        float reeds = 120.0;
        float groove = sin(angle * reeds + uTime * 0.5);
        normalMap.xy += groove * 0.15 * vec2(cos(angle), sin(angle));
        normalMap = normalize(normalMap);
      }

      // Apply normal map (tangent space approximation)
      vec3 T = normalize(vec3(-N.z, 0.0, N.x));
      vec3 B = cross(N, T);
      mat3 TBN = mat3(T, B, N);
      N = normalize(TBN * normalMap);

      float NdotV = max(dot(N, V), 0.0);
      float NdotL = max(dot(N, L), 0.0);
      float NdotH = max(dot(N, H), 0.0);
      float VdotH = max(dot(V, H), 0.0);

      // F0
      vec3 F0 = mix(vec3(0.04), baseColor, metalness);

      // BRDF
      float D = D_GGX(N, H, roughness);
      float G = G_Smith(N, V, L, roughness);
      vec3 F = F_Schlick(VdotH, F0);

      vec3 specular = D * G * F / (4.0 * NdotV * NdotL + 0.001);
      vec3 diffuse = (1.0 - F) * baseColor / PI * (1.0 - metalness);

      // Environment lighting (simplified IBL)
      vec3 R = reflect(-V, N);
      vec3 env = sampleEnv(R);
      vec3 envSpecular = env * F * metalness * 0.5;
      vec3 envDiffuse = env * baseColor * (1.0 - metalness) * 0.3;

      // Direct light
      vec3 lightColor = vec3(1.0, 0.95, 0.9) * 2.5; // Warm key light
      vec3 direct = (diffuse + specular) * lightColor * NdotL;

      // Fill light
      vec3 fillDir = normalize(vec3(-0.3, 0.5, -0.4));
      float fillNdotL = max(dot(N, fillDir), 0.0);
      vec3 fillColor = vec3(0.3, 0.35, 0.5) * 0.8;
      vec3 fill = diffuse * fillColor * fillNdotL;

      // Rim light
      float rim = pow(1.0 - NdotV, 3.0);
      vec3 rimColor = vec3(0.8, 0.7, 0.5) * rim * 0.6 * metalness;

      vec3 color = direct + fill + envSpecular + envDiffuse + rimColor;

      // Exposure/tonemap
      color = color / (color + vec3(1.0));
      color = pow(color, vec3(1.0/2.2));

      // Subtle vignette for hero
      if (uIsHero) {
        float vignette = 1.0 - 0.15 * length(vUv - 0.5) * 2.0;
        color *= vignette;
      }

      fragColor = vec4(color, 1.0);
    }
    `;

    this.program = this.createProgram(vsSource, fsSource);
    this.attribs = {
      pos: gl.getAttribLocation(this.program, 'aPos'),
      normal: gl.getAttribLocation(this.program, 'aNormal'),
      uv: gl.getAttribLocation(this.program, 'aUv'),
      face: gl.getAttribLocation(this.program, 'aFace')
    };
    this.uniforms = {
      model: gl.getUniformLocation(this.program, 'uModel'),
      view: gl.getUniformLocation(this.program, 'uView'),
      proj: gl.getUniformLocation(this.program, 'uProj'),
      time: gl.getUniformLocation(this.program, 'uTime'),
      reedAmplitude: gl.getUniformLocation(this.program, 'uReedAmplitude'),
      frontColor: gl.getUniformLocation(this.program, 'uFrontColor'),
      backColor: gl.getUniformLocation(this.program, 'uBackColor'),
      frontNormal: gl.getUniformLocation(this.program, 'uFrontNormal'),
      backNormal: gl.getUniformLocation(this.program, 'uBackNormal'),
      edgeColor: gl.getUniformLocation(this.program, 'uEdgeColor'),
      baseColor: gl.getUniformLocation(this.program, 'uBaseColor'),
      roughness: gl.getUniformLocation(this.program, 'uRoughness'),
      metalness: gl.getUniformLocation(this.program, 'uMetalness'),
      isHero: gl.getUniformLocation(this.program, 'uIsHero')
    };
  }

  createProgram(vs, fs) {
    const gl = this.gl;
    const compile = (src, type) => {
      const s = gl.createShader(type);
      gl.shaderSource(s, src);
      gl.compileShader(s);
      if (!gl.getShaderParameter(s, gl.COMPILE_STATUS)) {
        throw new Error(gl.getShaderInfoLog(s));
      }
      return s;
    };
    const vsShader = compile(vs, gl.VERTEX_SHADER);
    const fsShader = compile(fs, gl.FRAGMENT_SHADER);
    const prog = gl.createProgram();
    gl.attachShader(prog, vsShader);
    gl.attachShader(prog, fsShader);
    gl.linkProgram(prog);
    if (!gl.getProgramParameter(prog, gl.LINK_STATUS)) {
      throw new Error(gl.getProgramInfoLog(prog));
    }
    return prog;
  }

  initGeometry() {
    const gl = this.gl;
    // Coin: cylinder with 2 faces + edge
    // Segments around circumference
    const segments = 240; // High for smooth reeds
    const edgeSegments = 8; // Edge thickness segments

    const positions = [];
    const normals = [];
    const uvs = [];
    const faces = [];
    const indices = [];

    const radius = 1.0;
    const thickness = 0.15;
    const halfThick = thickness / 2;

    // Face vertices (front and back)
    for (let face = 0; face < 2; face++) {
      const z = face === 0 ? -halfThick : halfThick; // 0=front (-Z), 1=back (+Z)
      const faceId = face === 0 ? 1.0 : 2.0;
      const centerIdx = positions.length / 3;

      // Center
      positions.push(0, 0, z);
      normals.push(0, 0, face === 0 ? -1 : 1);
      uvs.push(0.5, 0.5);
      faces.push(faceId);

      // Ring
      for (let i = 0; i <= segments; i++) {
        const a = (i / segments) * Math.PI * 2;
        const x = Math.cos(a) * radius;
        const y = Math.sin(a) * radius;
        positions.push(x, y, z);
        normals.push(0, 0, face === 0 ? -1 : 1);
        uvs.push(0.5 + Math.cos(a) * 0.5, 0.5 + Math.sin(a) * 0.5);
        faces.push(faceId);
      }

      // Triangulate face (fan)
      for (let i = 1; i <= segments; i++) {
        indices.push(centerIdx, centerIdx + i, centerIdx + i + 1);
      }
    }

    // Edge geometry - cylindrical side
    const edgeFaceId = 0.0;
    for (let i = 0; i <= segments; i++) {
      const a = (i / segments) * Math.PI * 2;
      const nx = Math.cos(a);
      const ny = Math.sin(a);

      // Bottom edge (front face edge)
      positions.push(nx * radius, ny * radius, -halfThick);
      normals.push(nx, ny, 0);
      uvs.push(i / segments, 0);
      faces.push(edgeFaceId);

      // Top edge (back face edge)
      positions.push(nx * radius, ny * radius, halfThick);
      normals.push(nx, ny, 0);
      uvs.push(i / segments, 1);
      faces.push(edgeFaceId);
    }

    // Edge indices (quad strip)
    for (let i = 0; i < segments; i++) {
      const base = (positions.length / 3) - (segments + 1) * 2;
      const a = base + i * 2;
      const b = base + i * 2 + 1;
      const c = base + (i + 1) * 2;
      const d = base + (i + 1) * 2 + 1;
      indices.push(a, b, c);
      indices.push(c, b, d);
    }

    this.vertexCount = indices.length;

    this.vao = gl.createVertexArray();
    gl.bindVertexArray(this.vao);

    const buf = (data, attr, size) => {
      const b = gl.createBuffer();
      gl.bindBuffer(gl.ARRAY_BUFFER, b);
      gl.bufferData(gl.ARRAY_BUFFER, new Float32Array(data), gl.STATIC_DRAW);
      gl.enableVertexAttribArray(attr);
      gl.vertexAttribPointer(attr, size, gl.FLOAT, false, 0, 0);
      return b;
    };

    this.buffers = {
      pos: buf(positions, this.attribs.pos, 3),
      normal: buf(normals, this.attribs.normal, 3),
      uv: buf(uvs, this.attribs.uv, 2),
      face: buf(faces, this.attribs.face, 1)
    };

    this.indexBuffer = gl.createBuffer();
    gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER, this.indexBuffer);
    gl.bufferData(gl.ELEMENT_ARRAY_BUFFER, new Uint16Array(indices), gl.STATIC_DRAW);

    gl.bindVertexArray(null);
  }

  initTextures() {
    const gl = this.gl;
    const textures = createCoinTextures(this.metal);
    const frontNormal = createNormalMap(this.metal, 'front');
    const backNormal = createNormalMap(this.metal, 'back');

    const createTex = (canvas) => {
      const tex = gl.createTexture();
      gl.bindTexture(gl.TEXTURE_2D, tex);
      gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, canvas);
      gl.generateMipmap(gl.TEXTURE_2D);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR_MIPMAP_LINEAR);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
      return tex;
    };

    this.textures = {
      frontColor: createTex(textures.front),
      backColor: createTex(textures.back),
      frontNormal: createTex(frontNormal),
      backNormal: createTex(backNormal)
    };

    // Edge procedural - small texture
    const edgeCanvas = document.createElement('canvas');
    edgeCanvas.width = edgeCanvas.height = 256;
    const ctx = edgeCanvas.getContext('2d');
    const metals = {
      bronze: { base: '#cd7f32', light: '#e8a86b', dark: '#8b5a2b' },
      silver: { base: '#c0c0c0', light: '#f0f0f0', dark: '#888888' },
      gold: { base: '#ffd700', light: '#fff8a0', dark: '#b89600' },
      black: { base: '#0a0a0a', light: '#1a1a1a', dark: '#000000' }
    };
    const m = metals[this.metal];
    const grad = ctx.createLinearGradient(0, 0, 0, 256);
    grad.addColorStop(0, m.dark);
    grad.addColorStop(0.3, m.base);
    grad.addColorStop(0.5, m.light);
    grad.addColorStop(0.7, m.base);
    grad.addColorStop(1, m.dark);
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, 256, 256);
    this.textures.edgeColor = createTex(edgeCanvas);
  }

  initUniforms() {
    const metals = {
      bronze: { base: [0.80, 0.50, 0.20], rough: 0.35, metal: 0.9 },
      silver: { base: [0.75, 0.75, 0.78], rough: 0.15, metal: 0.98 },
      gold: { base: [1.0, 0.84, 0.0], rough: 0.1, metal: 1.0 },
      black: { base: [0.04, 0.04, 0.04], rough: 0.05, metal: 0.95 }
    };
    this.material = metals[this.metal];

    this.model = new Float32Array(16);
    this.view = new Float32Array(16);
    this.proj = new Float32Array(16);

    this.cameraDistance = this.isHero ? 3.5 : 2.8;
  }

  resize() {
    const gl = this.gl;
    const dpr = window.devicePixelRatio || 1;
    const rect = this.canvas.getBoundingClientRect();
    this.width = Math.floor(rect.width * dpr);
    this.height = Math.floor(rect.height * dpr);
    if (this.canvas.width !== this.width || this.canvas.height !== this.height) {
      this.canvas.width = this.width;
      this.canvas.height = this.height;
    }
    gl.viewport(0, 0, this.width, this.height);

    // Projection matrix
    const aspect = this.width / this.height;
    const fov = this.isHero ? 0.35 : 0.45; // Narrower FOV for hero = more orthographic
    const f = 1.0 / Math.tan(fov / 2);
    this.proj[0] = f / aspect; this.proj[1] = 0; this.proj[2] = 0; this.proj[3] = 0;
    this.proj[4] = 0; this.proj[5] = f; this.proj[6] = 0; this.proj[7] = 0;
    this.proj[8] = 0; this.proj[9] = 0; this.proj[10] = -1.0002; this.proj[11] = -1;
    this.proj[12] = 0; this.proj[13] = 0; this.proj[14] = -0.2; this.proj[15] = 0;
  }

  setTime(t) {
    this.time = t;
    this.render(t);
  }

  render(t) {
    const gl = this.gl;
    gl.useProgram(this.program);
    gl.bindVertexArray(this.vao);

    // Clear
    gl.clearColor(0.04, 0.04, 0.05, 1.0);
    gl.clear(gl.COLOR_BUFFER_BIT | gl.DEPTH_BUFFER_BIT);
    gl.enable(gl.DEPTH_TEST);
    gl.enable(gl.CULL_FACE);
    gl.cullFace(gl.BACK);
    gl.frontFace(gl.CCW);

    // Animation parameters
    // Y rotation: full 360 per loop
    // X rotation: 180 flip per loop (so both faces seen once)
    const yRot = t * Math.PI * 2;
    const xRot = t * Math.PI; // 0 to PI over loop

    // Model matrix
    const cy = Math.cos(yRot), sy = Math.sin(yRot);
    const cx = Math.cos(xRot), sx = Math.sin(xRot);

    // Model = Ry * Rx
    this.model[0] = cy; this.model[1] = 0; this.model[2] = -sy; this.model[3] = 0;
    this.model[4] = sy * sx; this.model[5] = cx; this.model[6] = cy * sx; this.model[7] = 0;
    this.model[8] = sy * cx; this.model[9] = -sx; this.model[10] = cy * cx; this.model[11] = 0;
    this.model[12] = 0; this.model[13] = 0; this.model[14] = 0; this.model[15] = 1;

    // View matrix - camera at distance on +Z
    const eyeZ = this.cameraDistance;
    this.view[0] = 1; this.view[1] = 0; this.view[2] = 0; this.view[3] = 0;
    this.view[4] = 0; this.view[5] = 1; this.view[6] = 0; this.view[7] = 0;
    this.view[8] = 0; this.view[9] = 0; this.view[10] = 1; this.view[11] = 0;
    this.view[12] = 0; this.view[13] = 0; this.view[14] = -eyeZ; this.view[15] = 1;

    // Uniforms
    gl.uniformMatrix4fv(this.uniforms.model, false, this.model);
    gl.uniformMatrix4fv(this.uniforms.view, false, this.view);
    gl.uniformMatrix4fv(this.uniforms.proj, false, this.proj);
    gl.uniform1f(this.uniforms.time, t);
    gl.uniform1f(this.uniforms.reedAmplitude, 0.008); // Reeded edge depth
    gl.uniform3fv(this.uniforms.baseColor, this.material.base);
    gl.uniform1f(this.uniforms.roughness, this.material.rough);
    gl.uniform1f(this.uniforms.metalness, this.material.metal);
    gl.uniform1i(this.uniforms.isHero, this.isHero ? 1 : 0);

    // Textures
    const bindTex = (tex, unit, loc) => {
      gl.activeTexture(gl.TEXTURE0 + unit);
      gl.bindTexture(gl.TEXTURE_2D, tex);
      gl.uniform1i(loc, unit);
    };
    bindTex(this.textures.frontColor, 0, this.uniforms.frontColor);
    bindTex(this.textures.backColor, 1, this.uniforms.backColor);
    bindTex(this.textures.frontNormal, 2, this.uniforms.frontNormal);
    bindTex(this.textures.backNormal, 3, this.uniforms.backNormal);
    bindTex(this.textures.edgeColor, 4, this.uniforms.edgeColor);

    gl.drawElements(gl.TRIANGLES, this.vertexCount, gl.UNSIGNED_SHORT, 0);

    gl.bindVertexArray(null);
    gl.useProgram(null);
  }

  start() {
    if (this.animId) return;
    this.paused = false;
    const loop = (time) => {
      if (this.paused) return;
      const t = (time * 0.0003) % 1; // ~3.3s per loop
      this.render(t);
      this.animId = requestAnimationFrame(loop);
    };
    this.animId = requestAnimationFrame(loop);
  }

  pause() {
    this.paused = true;
    if (this.animId) {
      cancelAnimationFrame(this.animId);
      this.animId = null;
    }
  }
}

